```go
package main
import ("fmt")
func First[T any](items []T) (T, bool) {
 if len(items) == 0 { var zero T; return zero, false }
 return items[0], true
}
func main() {
 value, ok := First([]int{7, 9})
 fmt.Println(value, ok)
}
```

